CREATE TABLE public.bots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    name text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    system_prompt text DEFAULT ''::text NOT NULL,
    model text DEFAULT 'claude-sonnet-4-6'::text NOT NULL,
    temperature numeric(20,4) DEFAULT 0.7 NOT NULL,
    max_tokens integer DEFAULT 1024 NOT NULL,
    welcome_message text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    conversation_count integer DEFAULT 0 NOT NULL,
    message_count integer DEFAULT 0 NOT NULL,
    deployed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone,
    "updatedAt" timestamp with time zone
);


